Object.assign(PERSONA_ABOUT, {"m008": {"about": "Dev is the one who fixes your bike before you've finished asking. He works at the shop below his parents' flat, laughs with his whole face, and will hand you a mango lassi like it settles an argument.", "short": "Easy company, always covered in chain grease.", "topics": [["🚲", "Cycling"], ["🎨", "Street art"], ["🥤", "Smoothies"]]}, "m013": {"about": "Kenji is quiet in a way that makes you lean in. He works in a camera shop, shoots film only, and answers a big question with one small true sentence. He'll lose at mini golf on purpose just to watch your face.", "short": "Quiet, observant, and funnier than he lets on.", "topics": [["📷", "Film photography"], ["⛳", "Mini golf"], ["🍵", "Tea"]]}, "m024": {"about": "Mateo grooms dogs for a living and smells like it. He's sunny and unbothered, gets excited about small things immediately, and rates every snack he eats out of ten with a completely straight face.", "short": "Sunny, easygoing, and a total dog person.", "topics": [["🛹", "Skating"], ["🐕", "Dogs"], ["🏖️", "Beach walks"]]}, "m061": {"about": "Theo hosts a student radio show and talks for a living, badly, by his own account. He talks fast but listens properly, and will ask you something you weren't ready for and then just wait.", "short": "Quick, warm, and genuinely curious.", "topics": [["⚽", "Football"], ["📻", "Radio"], ["🎵", "Music"]]}, "m001": {"about": "Luca studies literature, climbs on weekends and makes pasta from scratch. He's thoughtful and steady, and has a habit of giving an honest answer to a small question, which catches people off guard.", "short": "Thoughtful, steady, and quietly romantic about ordinary things.", "topics": [["🧗", "Bouldering"], ["🍳", "Cooking"], ["📸", "Photography"]]}, "m009": {"about": "Isaiah sprints for his university and hypes everyone else more than himself. He's calm and encouraging, goes shy about compliments, and knows exactly which fire escape has the best sunset.", "short": "Calm, encouraging, and shy about praise.", "topics": [["🏃", "Track"], ["👟", "Sneakers"], ["🌮", "Tacos"]]}, "m014": {"about": "Amari coaches kids' tennis and loses to them regularly. He's patient in the way only someone who teaches seven-year-olds can be, and his sneakers are lined up by how often he wears them.", "short": "Patient, funny, and good with people.", "topics": [["🎾", "Tennis"], ["🍳", "Cooking"], ["🌅", "Boardwalks"]]}, "m019": {"about": "Malik is a design student with three projects going and none finished, all of them interesting. His windowsill is cuttings in jam jars, and he names his plants after footballers and reports on their health.", "short": "Scattered in a charming way, full of ideas.", "topics": [["🛹", "Skating"], ["🪴", "Plants"], ["🏮", "Night markets"]]}, "m023": {"about": "Elias runs shifts at a laundromat and lives in the warm flat above it. He's deadpan on the surface and warm underneath, drops one dry line and lets it sit there.", "short": "Deadpan, warm underneath, hard to rattle.", "topics": [["🥟", "Dumplings"], ["🕹️", "Arcades"], ["🌧️", "Rainy days"]]}, "m040": {"about": "Omar helps coach basketball and is competitive about everything that doesn't matter. He has big energy and a quick laugh, makes pancakes for his younger brother every Sunday, and only ever shoots bank shots.", "short": "Big energy, quick laugh, bad loser.", "topics": [["🏀", "Basketball"], ["🍳", "Cooking"], ["🧢", "Streetwear"]]}, "m045": {"about": "Rafael projects films for a society in Lisbon and lives with his grandmother. He's gentle and a little formal at first, then opens up completely, and presses a flower from every place he likes.", "short": "Gentle, old-fashioned, surprisingly sentimental.", "topics": [["🎞️", "Film"], ["🌸", "Pressed flowers"], ["🍉", "Summer fruit"]]}, "m059": {"about": "Haruki works in an archive and comes home smelling faintly of indigo. He's soft-spoken and precise, notices the thing nobody mentioned, and apologises for his permanently blue fingertips before shaking hands.", "short": "Soft-spoken, precise, notices everything.", "topics": [["🧶", "Dyeing"], ["🗂️", "Archives"], ["🌅", "Mornings"]]}, "m064": {"about": "Nikolas assists at a ceramics studio and keeps every slightly wrong mug he's ever made. He's low-key and dependable, and his jokes land a beat late and land well.", "short": "Low-key, dependable, dryly funny.", "topics": [["🏺", "Pottery"], ["🍜", "Noodles"], ["🌧️", "Rain"]]}, "m066": {"about": "Dante studies music, drums on every surface within reach, and cooks for his mum and little sister on Wednesdays. He's relaxed and generous with his attention in a way you notice afterwards.", "short": "Relaxed, warm, always tapping something.", "topics": [["🥁", "Drums"], ["🥪", "Sandwiches"], ["🚌", "Night buses"]]}, "m042": {"about": "Sebastián develops prints in a darkroom above a print shop. He's reserved and watchful, dryly funny once he's warm, and talks about buildings like people and people like buildings.", "short": "Reserved, watchful, dry once he's comfortable.", "topics": [["📷", "Darkroom"], ["🤾", "Handball"], ["🏛️", "Architecture"]]}, "m054": {"about": "Finn works in a model shop and carries a half-repaired plane around in a shoebox. He's enthusiastic, slightly all over the place and completely impossible to dislike.", "short": "Enthusiastic, chaotic, impossible to dislike.", "topics": [["✈️", "Model planes"], ["🧭", "Cliff walks"], ["🎲", "Game nights"]]}, "m063": {"about": "Jonah walks dogs along the canals and knows every dog on his route by name and none of the owners. He's easygoing and kind, the friend everyone trusts with their keys.", "short": "Easygoing, kind, the reliable one.", "topics": [["🐕", "Dogs"], ["🍜", "Ramen"], ["🛶", "Canals"]]}, "m065": {"about": "Andrés assists at a music studio and turns his parents' garage into one at night. He's quiet until the subject is music, then he won't stop, and he blushes easily.", "short": "Quiet until it's about music, then unstoppable.", "topics": [["🏸", "Badminton"], ["🏺", "Pottery"], ["🎚️", "Recording"]]}, "m069": {"about": "Nate fixes boards at a skate shop and spends his days off out on desert trails. He's chilled out, unimpressed by most things, and surprisingly soft about cacti.", "short": "Chilled, unbothered, secretly soft about plants.", "topics": [["🛹", "Skating"], ["🏜️", "Desert hikes"], ["🍛", "Thai food"]]}, "m002": {"about": "Emilio is a personal trainer with an alarmingly organised fridge. He's upbeat and direct, remembers what you said last week and brings it up, and can jump rope through a whole conversation.", "short": "Upbeat, direct, remembers everything.", "topics": [["🏋️", "Training"], ["✈️", "Travel"], ["☕", "Cafés"]]}, "m006": {"about": "Ren is a florist living above his own shop in Tokyo. He's composed and particular, chooses his words the way he chooses stems, and folds a crane out of any receipt he's handed.", "short": "Composed, particular, quietly romantic.", "topics": [["💐", "Flowers"], ["🐦", "Origami"], ["🛵", "Scooters"]]}, "m011": {"about": "Oliver is a law trainee who never actually puts the violin away. He's measured and well-mannered, with a slyer sense of humour than the suit suggests.", "short": "Well-mannered, sharp, funnier than he looks.", "topics": [["🎻", "Violin"], ["⚓", "Harbours"], ["☕", "Cafés"]]}, "m015": {"about": "Cole makes coffee for a living and shares a house where the living room floor is the listening room. He's laid-back and welcoming, and will make you a drink before asking what's wrong.", "short": "Laid-back, welcoming, never on time.", "topics": [["☕", "Coffee"], ["💿", "Vinyl"], ["🏞️", "Lakes"]]}, "m016": {"about": "Jalen binds books by hand and rows before work. He's thoughtful and a bit private, gives short answers that turn out to be exactly right, and hands people notebooks instead of saying how he feels.", "short": "Private, thoughtful, says it in objects.", "topics": [["📔", "Bookbinding"], ["🚣", "Rowing"], ["🌧️", "Rain"]]}, "m020": {"about": "Niko coordinates a community garden and is the reason anything gets organised. He feeds everyone, forgets to eat himself, and carries a pocket kite he has definitely flown at a party.", "short": "Social glue, feeds everyone, forgets himself.", "topics": [["🔥", "Grilling"], ["🪁", "Kites"], ["🀄", "Dominoes"]]}, "m035": {"about": "Henry studies cello at a conservatory in a draughty Edinburgh flat. He has old-fashioned manners and a sharp mind, and narrates the weather like a radio announcer when it rains.", "short": "Formal, intense about music, quietly funny.", "topics": [["🎻", "Cello"], ["🪴", "Terrariums"], ["🌧️", "Rain"]]}, "m041": {"about": "Yusuf looks after aquariums and boxes in the evenings. He's serious on the surface and warm underneath, and says exactly what he means with nothing extra.", "short": "Serious, honest, warm once you know him.", "topics": [["🐠", "Aquariums"], ["🥊", "Boxing"], ["🍢", "Street food"]]}, "m051": {"about": "Gabriel works in a stationery shop and has the best window seat in his building. He's gentle, a little awkward and extremely sincere, and takes a beat before he answers.", "short": "Gentle, awkward, completely sincere.", "topics": [["🖋️", "Fountain pens"], ["🥎", "Softball"], ["🪟", "Window seats"]]}, "m007": {"about": "Jae-won tends bar in a hotel and reads a room instantly. He's smooth and attentive in a way that makes you feel like the only guest, and irons shirts at 1am to come down from a shift.", "short": "Smooth, attentive, never quite switches off.", "topics": [["🍸", "Cocktails"], ["🪡", "Tailoring"], ["🌇", "Rooftops"]]}, "m031": {"about": "Caleb keeps bees on his family's farm and makes the pie crust his grandmother taught him. He's calm the way people who work with bees are calm, and very easy to tell things to.", "short": "Calm, grounded, easy to talk to.", "topics": [["🐝", "Beekeeping"], ["🥖", "Baking"], ["🌉", "Footbridges"]]}, "m033": {"about": "Erik studies civil engineering and lives by the marina with a sailing friend. He's practical and quiet, explains things clearly and then stops talking.", "short": "Practical, quiet, completely unflappable.", "topics": [["⛵", "Sailing"], ["🌉", "Model bridges"], ["🛖", "Cabins"]]}, "m034": {"about": "Daniel owns a small tea shop and lives above it with a very old cat. He's composed and welcoming, has an opinion on everything and shares it politely.", "short": "Composed, opinionated, unfailingly polite.", "topics": [["🍵", "Tea"], ["🏸", "Badminton"], ["🌃", "City rooftops"]]}, "m039": {"about": "Aiden fixes outdoor gear and is the person you want with you when something breaks. He's steady and capable, and will repair your things uninvited and hand them back without mentioning it.", "short": "Steady, capable, quietly generous.", "topics": [["⛺", "Camping"], ["🔥", "Cooking outdoors"], ["🏛️", "Museums"]]}, "m044": {"about": "Arjun designs apps from a high floor with a very good view and very little furniture. He's sharp and well put together, a little guarded until he decides he likes you.", "short": "Sharp, polished, guarded at first.", "topics": [["🎾", "Squash"], ["🍳", "Cooking"], ["✏️", "Design"]]}, "m050": {"about": "Tomás mixes glazes at a ceramics studio and keeps a pouch of zip pulls for strangers. He's cool and a bit distant at first, then genuinely generous.", "short": "Cool at first, generous once you're in.", "topics": [["🏺", "Ceramics"], ["👕", "Vintage clothes"], ["🚇", "Metro rides"]]}, "m067": {"about": "Jack bakes bread and lives in the warm flat above the bakery. He's up before everyone, easy company, and permanently dusted with flour.", "short": "Early, warm, always slightly floury.", "topics": [["🥖", "Baking"], ["🚲", "Cycling"], ["🍎", "Orchards"]]}, "m068": {"about": "Felix works in a print studio and keeps a flat organised to the millimetre. He's precise and quiet, with dry humour that sneaks up on you.", "short": "Precise, quiet, sneakily funny.", "topics": [["🖨️", "Printmaking"], ["🎹", "Piano"], ["🥐", "Bakeries"]]}, "m021": {"about": "Takumi guides trails outside Sapporo and is comfortable in silence. He's economical with words and generous with time, and plans routes for trips he hasn't booked.", "short": "Economical with words, generous with time.", "topics": [["🥾", "Hiking"], ["🍜", "Noodles"], ["🗺️", "Maps"]]}, "m052": {"about": "Louis engineers sound in Lyon and keeps eleven bonsai on a strict schedule. He's particular and calm, and mends small broken things while he thinks.", "short": "Particular, calm, quietly fixing something.", "topics": [["🌲", "Bonsai"], ["🧵", "Sewing"], ["🎚️", "Recording"]]}, "m010": {"about": "Andre works leather above his own workshop, where the whole building smells of hide and allspice. He has quiet confidence and doesn't fill space he doesn't need to.", "short": "Quietly confident, no small talk.", "topics": [["🧰", "Leatherwork"], ["🍳", "Cooking"], ["🖼️", "Galleries"]]}, "m025": {"about": "Sami roasts coffee and has the roof set up for it year-round. He's warm and talkative about the things he loves, and quiet about himself.", "short": "Warm about everything except himself.", "topics": [["☕", "Coffee"], ["🥾", "Hiking"], ["🌇", "Rooftops"]]}, "m036": {"about": "Mathias weaves on a loom that has taken over his kitchen table. He's soft-spoken and deliberate, notices textures and mentions them.", "short": "Soft-spoken, deliberate, notices texture first.", "topics": [["🧶", "Weaving"], ["☕", "Espresso"], ["🚋", "Trams"]]}, "m038": {"about": "Diego coaches swimming on the Valencia coast and is in the water by six. He's high energy and encouraging, and a bit of a show-off about the sea.", "short": "High energy, encouraging, never indoors.", "topics": [["🏊", "Swimming"], ["🛶", "Kayaking"], ["🏸", "Badminton"]]}, "m058": {"about": "Arlo makes stained glass and lives somewhere every window has colour hanging in it. He's gentle and odd in a good way, and talks about light like it's a person.", "short": "Gentle, odd in the best way.", "topics": [["🪟", "Stained glass"], ["⛵", "Model boats"], ["🪴", "Glasshouses"]]}, "m070": {"about": "Rocco runs the ovens at his family's pizzeria and nobody there sleeps before two. He's loud, affectionate and slightly chaotic, and feeds people as a love language.", "short": "Loud, affectionate, feeds everyone.", "topics": [["🍕", "Pizza"], ["🥁", "Drums"], ["📚", "Bookshops"]]}, "m017": {"about": "Beau repairs watches and is very proud of his courtyard. He's unhurried and charming, slightly out of time, and notices the second hand on everything.", "short": "Unhurried, charming, pleasantly old-fashioned.", "topics": [["⌚", "Watches"], ["🍦", "Ice cream"], ["🌇", "Fire escapes"]]}, "m027": {"about": "Lucas is an architect with a beautiful, almost empty flat. He's precise and dryly funny, and will explain at length why a building is wrong.", "short": "Precise, dry, very particular.", "topics": [["🏛️", "Architecture"], ["🏓", "Table tennis"], ["🥖", "Baking"]]}, "m047": {"about": "Kwame makes electronic music from a studio that has slowly eaten his living room. He's inventive and scattered, jumps between ideas and takes you with him.", "short": "Inventive, scattered, never finishes a track.", "topics": [["🎛️", "Synths"], ["🪴", "Plants"], ["🌧️", "Rain"]]}, "m053": {"about": "Ignacio restores broken things and keeps shelves of mended cups nobody else wanted. He's careful and quietly romantic about the idea that broken things are worth keeping.", "short": "Careful, patient, sentimental about repairs.", "topics": [["🛠️", "Restoration"], ["🧩", "Puzzles"], ["🏞️", "River walks"]]}, "m056": {"about": "Ilias repairs cameras at a bench facing the sea. He's slow-talking and thoughtful, comfortable being looked at and uninterested in being impressive.", "short": "Slow, thoughtful, entirely unbothered.", "topics": [["📷", "Film cameras"], ["🏮", "Lanterns"], ["🎧", "Listening rooms"]]}, "m062": {"about": "Jonas teaches guitar and splits his time between a flat in town and the family cabin. He's grounded and warm, with the kind of calm that makes people say more than they meant to.", "short": "Grounded, warm, easy to open up to.", "topics": [["🎸", "Guitar"], ["🍳", "Cooking"], ["🌊", "Cliffs"]]}, "m004": {"about": "Karim lectures in literature and lives in a flat lined with books. He's articulate and warm, quotes things without being insufferable, and his mother calls every evening.", "short": "Articulate, warm, incapable of a short answer.", "topics": [["📚", "Books"], ["🥖", "Baking"], ["🚆", "Trains"]]}, "m018": {"about": "Rami fixes motorcycles and lives somewhere the garage is bigger than the kitchen. He's direct and unbothered, and says the true thing rather than the nice version.", "short": "Direct, unbothered, allergic to flattery.", "topics": [["🏍️", "Motorcycles"], ["🍳", "Cooking"], ["🏜️", "Desert"]]}, "m022": {"about": "Emre rigs lighting for theatre and shares a flat where nothing matches. He's dramatic in the fun way, tells stories with his hands and loses the thread happily.", "short": "Dramatic, warm, terrible sleep schedule.", "topics": [["🎭", "Theatre"], ["🍳", "Cooking"], ["🏙️", "Covered passages"]]}, "m026": {"about": "Dylan writes backend code and has an immaculate desk in an otherwise undisturbed flat. He's understated and precise, and funnier over text than in person, which he knows.", "short": "Understated, precise, better over text.", "topics": [["⌨️", "Keyboards"], ["🌿", "Herbs"], ["🥃", "Lounges"]]}, "m029": {"about": "Idris coaches cycling in Casablanca and never misses Friday lunch with his mother and aunt. He's attentive and encouraging, asks follow-up questions that prove he was listening.", "short": "Attentive, encouraging, family first.", "topics": [["🚲", "Cycling"], ["🍳", "Cooking"], ["🖼️", "Art centres"]]}, "m046": {"about": "Vikram is a research librarian whose hallway is a bookshelf. He's softly spoken and very well read, and hands you a book instead of an opinion.", "short": "Softly spoken, well read, never speaks first.", "topics": [["📚", "Libraries"], ["🍳", "Cooking"], ["🌧️", "Rain"]]}, "m060": {"about": "Xavier manages a tennis club and the courtyard fills up most evenings whether he invited anyone or not. He's charismatic and pulls people into whatever's happening.", "short": "Charismatic, generous, the host by default.", "topics": [["🎾", "Tennis"], ["🍳", "Cooking"], ["🀄", "Dominoes"]]}, "m032": {"about": "Terrence is a corporate lawyer in a high-rise where the kitchen is the only lived-in room. He's assured and courteous, and comfortable with silences in a way that unnerves people.", "short": "Assured, courteous, hard to read.", "topics": [["⌚", "Watches"], ["🥖", "Baking"], ["🚆", "Trains"]]}, "m043": {"about": "Noel photographs for a living and keeps a fridge that's mostly condiments. He's smooth and observant, and directs a room without appearing to.", "short": "Smooth, observant, quietly in charge.", "topics": [["📸", "Photography"], ["🍳", "Cooking"], ["⛵", "Marinas"]]}, "m037": {"about": "Adrian coaches strength training and lives with an elderly dog called Bor. He's blunt but not unkind, says less than he thinks and means all of it.", "short": "Blunt, dependable, surprisingly soft about the dog.", "topics": [["🏋️", "Training"], ["🍳", "Cooking"], ["🥾", "Hiking"]]}, "m057": {"about": "Julian engineers audio systems and has a listening room better furnished than his bedroom. He's calm and exacting, and takes sound personally.", "short": "Calm, exacting, no background music.", "topics": [["🔊", "Hi-fi"], ["📖", "Reading"], ["🎭", "Opera"]]}, "m071": {"about": "Viktor couriers on a bike that lives in his hallway. He's stoic and watchful, and warmer than his face suggests once you get past the first ten minutes.", "short": "Stoic, watchful, warmer than he looks.", "topics": [["🏍️", "Motorcycles"], ["🍳", "Cooking"], ["🌫️", "Fog"]]}, "m048": {"about": "Peter makes furniture in a workshop out back with a cat asleep in the shavings. He's measured and gentle, takes a long time to answer, and it's always worth it.", "short": "Measured, gentle, never rushed.", "topics": [["🪵", "Woodwork"], ["☕", "Coffee"], ["🛖", "Cabins"]]}, "m012": {"about": "Paulo owns a café in Porto and lives above it with a badly behaved dog. He's relaxed and generous, treats regulars like family and strangers like future regulars.", "short": "Relaxed, generous, never closes early.", "topics": [["☕", "Coffee"], ["🐕", "Dogs"], ["🎬", "Cinema"]]}, "m030": {"about": "Scott guides fly fishing in Calgary and his dining table seats ten and usually does. He's open and unhurried, asks good questions and actually waits for the answer.", "short": "Open, unhurried, feeds a crowd.", "topics": [["🎣", "Fly fishing"], ["🍳", "Cooking"], ["🏔️", "Mountains"]]}, "m003": {"about": "Marcus runs a record shop in Memphis and has a listening room and a very full spice shelf. He's settled and funny, with a story for everything and the sense to keep them short.", "short": "Settled, funny, knows a lot about very little.", "topics": [["💿", "Records"], ["🍳", "Cooking"], ["🧺", "Markets"]]}, "m005": {"about": "Graham is a golf pro whose backyard pizza oven gets more use than his kitchen. He has easy authority, is a bit formal, and melts entirely around good food.", "short": "Easy authority, formal, soft about food.", "topics": [["⛳", "Golf"], ["🍕", "Pizza"], ["🌊", "Coast walks"]]}, "m028": {"about": "Alan coaches chess and lives above a bookshop with a game permanently mid-play. He's patient and precise, and enjoys being wrong roughly once a year.", "short": "Patient, precise, slow on purpose.", "topics": [["♟️", "Chess"], ["🥾", "Hiking"], ["🎶", "Concerts"]]}, "m049": {"about": "Stefan is an urban planner with a very productive balcony herb garden. He's considered and a little reserved, and warms up considerably about cities.", "short": "Considered, reserved, passionate about cities.", "topics": [["🚲", "Cycling"], ["🌱", "Gardening"], ["🌆", "Cities"]]}, "m055": {"about": "Dario directs creative work in Milan from a flat that is also slightly a showroom. He's elegant and warm, very aware of how things look and not sorry about it.", "short": "Elegant, warm, unapologetically particular.", "topics": [["✏️", "Design"], ["🥖", "Baking"], ["🛎️", "Hotels"]]}, "g010": {"about": "Yuki is a fashion student whose flat is about sixty percent fabric. They're bright and expressive, talk with their hands, and are completely uninterested in being anyone's idea of normal.", "short": "Bright, expressive, entirely themselves.", "topics": [["👔", "Fashion"], ["🧴", "Perfume"], ["🏡", "Courtyards"]]}, "g003": {"about": "Jun studies ceramics near the water in Busan and won't close the window the fog comes through. He's quiet and watchful, and opens up in writing long before he does out loud.", "short": "Quiet, watchful, says it better in writing.", "topics": [["🏺", "Pottery"], ["🌊", "Coast walks"], ["📓", "Journaling"]]}, "g013": {"about": "Rory works in a vintage shop and shares a flat with three people and an alarming number of lamps. He's chatty and affectionate, and makes friends with everyone in the queue.", "short": "Chatty, warm, friends with the whole queue.", "topics": [["🕰️", "Vintage"], ["✏️", "Drawing"], ["🏞️", "Riversides"]]}, "g001": {"about": "Mateus makes candles in a small flat that smells like whatever he poured that week. He's composed and a little guarded, with dry wit and very deliberate taste.", "short": "Composed, guarded, very deliberate.", "topics": [["🕯️", "Candles"], ["👔", "Fashion"], ["🏡", "Courtyards"]]}, "g021": {"about": "Elio apprentices at a glassblowing studio while his aunt waits for it to be a phase. He's soft and focused, gets absorbed, forgets to reply and then apologises too much.", "short": "Soft, focused, apologises too much.", "topics": [["🫙", "Glass"], ["🐦", "Origami"], ["🚲", "Cycling"]]}, "g012": {"about": "Caspian works at a garden centre and shares a house with a greenhouse that's technically a shed. He's gentle and funny, the friend who brings cake to a crisis.", "short": "Gentle, funny, brings cake to a crisis.", "topics": [["🌱", "Gardening"], ["🥖", "Baking"], ["🧵", "Sewing"]]}, "g016": {"about": "Tobias screen-prints in Hamburg and argues with his best friend about the drying rack daily. He's scattered and warm, says three things at once and means all of them.", "short": "Scattered, warm, says everything at once.", "topics": [["🖨️", "Printmaking"], ["🎾", "Tennis"], ["🎵", "Music"]]}, "g004": {"about": "Noa dances ballet and lives with a cat who sits in the window all day. They're delicate and precise in how they move and talk, and private right up until they aren't.", "short": "Precise, private, quietly intense.", "topics": [["🩰", "Ballet"], ["💐", "Flowers"], ["🐈", "Cats"]]}, "g008": {"about": "Zain roasts coffee and shares a dining table that's half roastery, half paint station. He's understated and observant, answers questions exactly and never more.", "short": "Understated, observant, never exaggerates.", "topics": [["☕", "Coffee"], ["🖌️", "Miniature painting"], ["🚗", "Driving"]]}, "g015": {"about": "Kai coaches skating in Barcelona and lives somewhere the hallway is, legally speaking, a ramp. They're playful and restless, and turn a normal afternoon into a whole thing.", "short": "Playful, restless, never a quiet Saturday.", "topics": [["🛹", "Skating"], ["🛼", "Roller skating"], ["🧺", "Picnics"]]}, "g009": {"about": "Dominik instructs climbing in Budapest from a stairwell flat with very good light at six. He's confident and low-key, and checks on people without making it a thing.", "short": "Confident, low-key, quietly looks after people.", "topics": [["🧗", "Climbing"], ["🕯️", "Candles"], ["🌇", "Rooftops"]]}, "g020": {"about": "Mai assists a perfumer and lives above an antiques shop where everything has a history. She's elegant and deliberate, and will choose one perfect sentence over five good ones.", "short": "Elegant, deliberate, never rushed.", "topics": [["🧴", "Perfume"], ["🕰️", "Antiques"], ["🪴", "Conservatories"]]}, "g002": {"about": "Tyrone teaches surfing in Santa Cruz with a board permanently in the hallway. He's sunny and grounded, easy to talk to and impossible to hurry.", "short": "Sunny, grounded, entirely unhurried.", "topics": [["🏄", "Surfing"], ["🪵", "Woodwork"], ["🍳", "Diners"]]}, "g019": {"about": "Marco illustrates plants in Rio and keeps a plant press under the sofa. He's warm and chatty, and shows you things on his phone constantly.", "short": "Warm, chatty, always has something to show you.", "topics": [["🖊️", "Illustration"], ["🧵", "Sewing"], ["🪴", "Plants"]]}, "g006": {"about": "Alex styles interiors and lives in a flat styled to within an inch of its life. She's immaculate and dryly funny, with strong opinions about chairs.", "short": "Immaculate, dry, opinionated about furniture.", "topics": [["🛋️", "Styling"], ["🍵", "Tea"], ["🛎️", "Design hotels"]]}, "g024": {"about": "Ezra consults on branding in Cape Town and keeps a balcony jungle on a strict watering schedule. He's smooth and self-possessed, and compliments precisely and rarely.", "short": "Smooth, self-possessed, precise with praise.", "topics": [["🪡", "Tailoring"], ["🪴", "Plants"], ["🌇", "Rooftops"]]}, "g011": {"about": "Josiah coaches running in Atlanta and is up at five whether he wants to be or not. He's encouraging and steady, and remembers your goals and asks about them.", "short": "Encouraging, steady, remembers your goals.", "topics": [["🏃", "Running"], ["🍳", "Cooking"], ["🖼️", "Galleries"]]}, "g017": {"about": "Rafa manages a bar in Mexico City in a building full of people he's never spoken to. He's cool and composed, with a sharp line ready when you least expect it.", "short": "Cool, composed, quietly sharp.", "topics": [["🍸", "Cocktails"], ["✏️", "Design"], ["🌙", "Night walks"]]}, "g022": {"about": "Ishaan writes about music in Mumbai and shares a flat with a drummer, so neither sleeps normally. He talks in tangents, always three recommendations deep.", "short": "Enthusiastic, tangential, impossible to shut up.", "topics": [["🎵", "Music"], ["✍️", "Writing"], ["⛴️", "Ferries"]]}, "g023": {"about": "Minseo teaches ceramics in Seoul and has eleven wind chimes and one annoyed neighbour. He's soft and attentive, teaches patiently and apologises for things that aren't his fault.", "short": "Soft, attentive, apologises constantly.", "topics": [["🏺", "Ceramics"], ["🍳", "Cooking"], ["♨️", "Bathhouses"]]}, "g018": {"about": "Ollie teaches swimming two blocks from the beach and the balcony is always drying something. He's big, friendly, slightly too much in the best way, and remembers everyone's name.", "short": "Big, friendly, remembers your name.", "topics": [["🏊", "Swimming"], ["🍳", "Cooking"], ["🌃", "Nightlife"]]}, "g026": {"about": "Milo archives audio in Rotterdam and owns a turntable worth more than the rest of the flat. He's quiet and exact, and warm in a way that takes a while to notice.", "short": "Quiet, exact, warm once you notice.", "topics": [["💿", "Records"], ["🥖", "Baking"], ["🪴", "Greenhouses"]]}, "g014": {"about": "Giulia designs costume in Rome and keeps one room entirely as rails of clothes. She's theatrical and precise, and dresses for the version of the evening she intends to have.", "short": "Theatrical, precise, always overdressed on purpose.", "topics": [["🧵", "Costume"], ["🍵", "Tea"], ["🌇", "Rooftops"]]}, "g028": {"about": "Phoenix marbles paper in Portland and keeps a garden strung with lights all year. They're calm and curious, ask unusual questions and listen to the whole answer.", "short": "Calm, curious, a very good listener.", "topics": [["🎨", "Marbling"], ["🧺", "Picnics"], ["🌿", "Gardens"]]}, "g005": {"about": "Hiro is a florist living above his shop in Kyoto, where the courtyard is swept every morning. He's serene and exacting, says little and means all of it.", "short": "Serene, exacting, says very little.", "topics": [["💐", "Flowers"], ["🌊", "Coast walks"], ["🎷", "Jazz"]]}, "g025": {"about": "Laurent paints watercolours in Geneva and chose his flat for its north-facing window. He's refined and gently amused by everything, himself included.", "short": "Refined, amused, never paints indoors.", "topics": [["🎨", "Painting"], ["🍵", "Tea rooms"], ["⛴️", "Ferries"]]}, "g007": {"about": "Tarek coaches boxing in Dubai and is up before dawn and in bed before most people eat. He's disciplined and direct, and surprisingly tender about food and mornings.", "short": "Disciplined, direct, soft about mornings.", "topics": [["🥊", "Boxing"], ["🍳", "Cooking"], ["🌄", "Desert dawns"]]}, "g030": {"about": "Wei practises calligraphy in a Shanghai courtyard flat and in the square at dawn. He's reserved and gracious, and lets a silence sit without minding it.", "short": "Reserved, gracious, comfortable in silence.", "topics": [["🖌️", "Calligraphy"], ["🪁", "Kites"], ["🎷", "Jazz"]]}, "g027": {"about": "Farhan designs textiles in Karachi and has a conservatory full of dyed swatches drying. He's elegant and warm, and notices fabric before faces, then apologises for it.", "short": "Elegant, warm, fabric first.", "topics": [["🧶", "Textiles"], ["⛵", "Sailing"], ["🌧️", "Rain"]]}, "g029": {"about": "Benedikt is a tailor living above his shop with a courtyard garden he waters in the rain anyway. He's kind and unhurried, with a craftsman's habit of looking at you twice.", "short": "Kind, unhurried, looks twice at everything.", "topics": [["🪡", "Tailoring"], ["🌿", "Gardens"], ["🏡", "Courtyards"]]}});
